/* fadeInUp / fadeInRight, tied to scroll: over the first 220px after the element's top enters
   the window (a fixed distance, so anything in the first screen is in place at load).
   Each step starts 40px later. */
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .rollers-rise {
      animation: rollers-rise-up linear both;
      animation-timeline: view();
      animation-range: entry calc(var(--rollers-rise-step, 0) * 40px) entry calc(220px + var(--rollers-rise-step, 0) * 40px);
    }
    .rollers-rise.rollers-rise-right {
      animation-name: rollers-rise-left;
    }
  }
}

@keyframes rollers-rise-up {
  from {
    opacity: 0;
    transform: translateY(40px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes rollers-rise-left {
  from {
    opacity: 0;
    transform: translateX(60px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

import type { CSSProperties, ElementType, ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./rollers-rise.css";

export interface RollersRiseProps {
  children?: ReactNode;
  /** the element to render (div by default) */
  as?: ElementType;
  /** below: rise 40px into place (the original's fadeInUp) · right: slide in 60px from the right (fadeInRight) */
  from?: "below" | "right";
  /** position in a staggered row: 0, 1, 2… each arrives 40px of scroll later */
  step?: number;
  className?: string;
}

/** A wrapper that fades its content in and moves it into place over the first 220px of scroll
    after it enters the window (CSS view timeline). */
export function RollersRise({ children, as: Tag = "div", from = "below", step = 0, className }: RollersRiseProps) {
  return (
    <Tag
      className={cn("rollers-rise", from === "right" && "rollers-rise-right", className)}
      style={{ "--rollers-rise-step": step } as CSSProperties}
    >
      {children}
    </Tag>
  );
}
